window.AUTH=window.AUTH||{};window.AUTH["15-109"]={"d":"15-109","id":"2015/15-109","n":"Simmons v. Himmelreich","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioners","date":"2015-12-28","url":"https://www.justice.gov/osg/media/814836/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/simmons-et-al-v-himmelreich","n":117},{"k":"reply","label":"Reply brief for the petitioners","date":"2016-03-04","url":"https://www.justice.gov/osg/media/824266/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/simmons-et-al-v-himmelreich-0","n":51}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep578/usrep578621/usrep578621.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"2, 45"}},{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 37"}},{"t":"case","label":"Allen v. United States","cite":"816 F.2d 1417","y":1987,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/816/1417/","sum":"Holding that Section 2680(a) applies and reversing district court’s judgment against United States after extensive trial involving 98 witnesses, 1692 documentary exhibits, and 273-page district court opinion, see 588 F. Supp. 247 (D. Utah 1984).","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Anderson v. United States","cite":"317 F.3d 1235","y":2003,"url":"https://www.courtlistener.com/c/F.3d/317/1235/","by":{"0":"38"}},{"t":"case","label":"Andrews v. United States","cite":"121 F.3d 1430","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/121/1430/","sum":"Holding that United States was entitled to judgment of dismissal under Section 2680(a), after full trial.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Angel v. Bullington","cite":"330 U.S. 183","y":1947,"id":"scdb/1946-055","sc":1,"sum":"The identical issue having been finally adjudicated in the state courts and the cause of action being barred there, it may not be relitigated in the federal courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 33, 35, 36","1":"16, 17"}},{"t":"case","label":"Aragon v. United States","cite":"146 F.3d 819","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/146/819/","by":{"0":"26"}},{"t":"case","label":"Audio Odyssey, Ltd. v. United States","cite":"255 F.3d 512","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/255/512/","by":{"0":"47","1":"9"}},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Barnson v. United States","cite":"816 F.2d 549","y":1987,"url":"https://www.courtlistener.com/c/F.2d/816/549/","sum":"Noting “extensive discovery” before district court granted summary judgment to United States under Section 2680(a).","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Begay v. United States","cite":"768 F.2d 1059","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/768/1059/","by":{"0":"25"}},{"t":"case","label":"Bilski v. Kappos","cite":"561 U.S. 593","y":2010,"id":"2009/08-964","sc":1,"sum":"The Court held that the \"machine-or-transformation\" test adopted by the Patent and Trademark Office (PTO) was a legal means for determining patent eligibility.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"ar":18,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Blackburn v. United States","cite":"100 F.3d 1426","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/100/1426/","sum":"Rejecting plaintiff’s argument that “120 days of discovery” in which United States “produced thousands of pages of documents” was insufficient for purposes of litigating applicability of Section 2680(a).","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Bloomquist v. Brady","cite":"894 F. Supp. 108","y":1995,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./894/108/","by":{"0":"38"}},{"t":"case","label":"Broadway Open Air Theatre v. United States","cite":"208 F.2d 257","y":1953,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/208/257/","by":{"0":"20"}},{"t":"case","label":"Burrows v. United States","cite":"120 Fed. Appx. 448","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./120/448/","by":{"0":"47"}},{"t":"case","label":"Coffey v. United States","cite":"906 F. Supp. 2d 1114","y":2012,"court":"D.N.M.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/906/1114/","by":{"0":"26"}},{"t":"case","label":"Dalehite v. United States","cite":"346 U.S. 15","y":1953,"id":"scdb/1952-101","sc":1,"op":1,"sum":"As a matter of law, the facts found by the District Court cannot give it jurisdiction of the cause under the Act, because the claim is \"based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the plirt of a federal agency or an employee of the Government,\" within the meaning of 28 U. S. C. § 2680 (a), which makes the Act inapplicable to such claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3, 5, 23, 25","1":"7, 8"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Davric Me. Corp. v. United States Postal Serv.","cite":"238 F.3d 58","y":2001,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/238/58/","ar":1,"by":{"0":"47","1":"9"}},{"t":"case","label":"Domme v. United States","cite":"61 F.3d 787","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/61/787/","by":{"0":"5"}},{"t":"case","label":"Farmer v. Perrill","cite":"275 F.3d 958","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/275/958/","by":{"0":"6"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 45, 46, 47","1":"8, 11"}},{"t":"case","label":"Flores v. Edinburg Consol. Indep. Sch. Dist.","cite":"741 F.2d 773","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/741/773/","by":{"0":"38"}},{"t":"case","label":"Formula One Motors, Ltd. v. United States","cite":"777 F.2d 822","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/777/822/","by":{"0":"5"}},{"t":"case","label":"Franklin Sav. Corp. v. United States","cite":"180 F.3d 1124","y":1999,"url":"https://www.courtlistener.com/c/F.3d/180/1124/","by":{"0":"47","1":"9"}},{"t":"case","label":"Frigard v. United States","cite":"862 F.2d 201","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/862/201/","by":{"0":"35, 38"}},{"t":"case","label":"Gasho v. United States","cite":"39 F.3d 1420","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/39/1420/","by":{"0":"6, 24"}},{"t":"case","label":"Goodwill Indus. of El Paso v. United States","cite":"218 F.2d 270","y":1954,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/218/270/","by":{"0":"20"}},{"t":"case","label":"Great W. Ins. Co. v. United States","cite":"112 U.S. 193","y":1884,"id":"scdb/1884-028","sc":1,"sum":"A claim 'against the United States for a part of the money received from Great Britain in payment of the award made at Geneva under the Treaty of Washington, is both a claim growing out of a treaty stipulation and a claim dependent upon such stipulation, and is excluded from the jurisdiction of the Court of Claims by § 1066 ReV. Stat.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Hallock v. Bonner","cite":"387 F.3d 147","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/387/147/","op":1,"by":{"0":"6, 41"}},{"t":"case","label":"Harris v. United States","cite":"422 F.3d 322","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/422/322/","by":{"0":"10"}},{"t":"case","label":"Hart v. United States","cite":"630 F.3d 1085","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/630/1085/","by":{"0":"38"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Herring v. Winston-Salem/Forsyth Cnty. Bd. of Educ.","cite":"656 S.E.2d 307","y":2008,"court":"N.C. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/656/307/","by":{"0":"38"}},{"t":"case","label":"Hoosier Bancorp of Ind., Inc. v. Rasmussen","cite":"90 F.3d 180","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/90/180/","by":{"0":"6"}},{"t":"case","label":"Indian Towing Co. v. United States","cite":"350 U.S. 61","y":1955,"id":"1955/8","sc":1,"ar":1,"sum":"If the Coast Guard is negligent in the operation of a lighthouse and damage is caused thereby, the United States is liable under the Tort Claims Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 13, 34"}},{"t":"case","label":"Insurance Corp. of Ir., Ltd., v. Compagnie des Bauxites de Guinee","cite":"456 U.S. 694","y":1982,"id":"1981/81-440","sc":1,"sum":"Federal Rule of Civil Procedure 37(b)(2)(A) provides that a district court, as a sanction for failure to comply with discovery orders, may enter \"[ain order that the matters regarding which the [discovery] order was made or any other designated facts shall be taken to be established for the purposes of the action in accordance with the claim of the party obtaining the order.\" Asserting diversity jurisdiction, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Irving v. United States","cite":"532 F. Supp. 840","y":1982,"court":"D.N.H.","url":"https://www.courtlistener.com/c/F.%20Supp./532/840/","by":{"0":"27"}},{"t":"case","label":"Irving v. United States","cite":"162 F.3d 154","y":1999,"url":"https://www.courtlistener.com/c/F.3d/162/154/","sum":"Holding that United States was entitled to judgment under Section 2680(a), after nearly 20 years of litigation and three separate appeals.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Johnson v. United States","cite":"170 F.2d 767","y":1948,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/170/767/","by":{"0":"21"}},{"t":"case","label":"Jones v. United States","cite":"228 F.2d 52","y":1955,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/228/52/","by":{"0":"38"}},{"t":"case","label":"Kelly v. United States","cite":"241 F.3d 755","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/241/755/","sum":"Holding that United States was entitled to judgment of dismissal under Section 2680(a), after full trial.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Kosak v. United States","cite":"465 U.S. 848","y":1984,"id":"1983/82-618","sc":1,"sum":"Section 2680(c) precludes recovery against the United States for the alleged injury to petitioner's property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 35"}},{"t":"case","label":"Kutzik v. Young","cite":"730 F.2d 149","y":1984,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/730/149/","by":{"0":"38"}},{"t":"case","label":"Lamie v. United States Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Levin v. United States","cite":"133 S. Ct. 1224","y":2013,"id":"2012/11-1351","sc":1,"ar":2,"sum":"The Court held that the Gonzalez Act made an exception to the Federal Tort Claims Act by saying that a claim of the intentional tort of battery may be brought against an armed forces physician.","sumSrc":"Oyez","by":{"0":"4, 34"}},{"t":"case","label":"Limone v. United States","cite":"497 F. Supp. 2","y":2007,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp./497/2/","by":{"0":"26"}},{"t":"case","label":"Loughlin v. United States","cite":"286 F. Supp. 2d 1","y":2003,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/286/1/","sum":"Noting “six months” of “extensive discovery” regarding applicability of Section 2680(a).","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Midwest Knitting Mills, Inc. v. United States","cite":"741 F. Supp. 1345","y":1990,"court":"E.D. Wis.","url":"https://www.courtlistener.com/c/F.%20Supp./741/1345/","by":{"0":"38"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Molzof v. United States","cite":"502 U.S. 301","y":1992,"id":"1991/90-838","sc":1,"sum":"The District Court awarded the guardian ad litem of petitioner Molzof's since-deceased husband damages under the Federal Tort Claims Act (FTCA or Act) for supplemental medical care for injuries suffered by Mr. Molzof as a result of the negligence of federal employees, but refused to award damages for future medical expenses and for loss of enjoyment of life. The Court of Appeals affirmed, ruling that damages of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"19"}},{"t":"case","label":"Morton v. United States","cite":"228 F.2d 431","y":1955,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/228/431/","by":{"0":"20"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"134 S. Ct. 1749","y":2014,"id":"2013/12-1184","sc":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"16, 21"}},{"t":"case","label":"Panella v. United States","cite":"216 F.2d 622","y":1954,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/216/622/","by":{"0":"20"}},{"t":"case","label":"Parklane Hosiery Co. v. Shore","cite":"439 U.S. 322","y":1979,"id":"1978/77-1305","sc":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Pesnell v. Arsenault","cite":"543 F.3d 1038","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/543/1038/","op":1,"by":{"0":"41, 42, 43","1":"22"}},{"t":"case","label":"Postum Cereal Co. v. California Fig Nut Co.","cite":"272 U.S. 693","y":1927,"id":"scdb/1926-046","sc":1,"sum":"1. A proceeding in the Court of Appeals of the District of Columbia under § 9 of the Trade Mark Act of 1905, to review a decision of the Commissioner of Patents refusing to cancel the registration of a trade mark, is an administrative matter, and not a \"case\" within the meaning of Art. III of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Rayonier v. United States","cite":"352 U.S. 315","y":1957,"id":"1956/45","sc":1,"sum":"Under the Federal Tort Claims Act, the United States is not immune from liability for negligence of employees of the Forest Service in fighting a fire, if in similar circumstances a private person would be liable under the laws of the State in which the fire occurred. Pp. 315-321. 225 F. 2d 642, 650, judgments vacated and causes remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Richards v. United States","cite":"369 U.S. 1","y":1962,"id":"1961/59","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","1":"16"}},{"t":"case","label":"Richardson v. United States","cite":"943 F.2d 1107","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/943/1107/","by":{"0":"5"}},{"t":"case","label":"Robers v. United States","cite":"134 S. Ct. 1854","y":2014,"id":"2013/12-9012","sc":1,"sum":"The Court held that, under the Mandatory Victims Restitution Act, individuals accused of property crime must pay “an amount equal to...the value of the property,” minus “the value...of any part of the property that is returned\" in retribution.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Rodriguez v. Handy","cite":"873 F.2d 814","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/873/814/","by":{"0":"6"}},{"t":"case","label":"Rose v. Town of Harwich","cite":"778 F.2d 77","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/778/77/","sum":"Explaining that “jurisdictional” exception applies to cases dismissed based on “defects of a technical or procedural nature which, if cured, normally ought not to bar a plaintiff from bringing the action again”.","sumSrc":"brief:0","by":{"0":"13, 36, 37, 39","1":"14, 15"}},{"t":"case","label":"Saunders v. Bush","cite":"15 F.3d 64","y":1994,"url":"https://www.courtlistener.com/c/F.3d/15/64/","by":{"0":"38"}},{"t":"case","label":"Schiro v. Farley","cite":"510 U.S. 222","y":1994,"id":"1993/92-7549","sc":1,"sum":"At petitioner Schiro's state court trial on three counts of murder-including, in Count I, the charge that he \"knowingly\" killed the victim, and, in Count II, that he killed her while committing rape-the jury returned a verdict of guilty on Count II, but left the remaining verdict sheets blank. The trial court imposed the death sentence, finding that the State had proved the statutory aggravating factor that Schiro …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"sum":"The Court held that \"[b]ecause the claim-preclusive effect of a federal court's dismissal 'upon the merits' of a diversity action on state statute-of-limitations grounds is governed by a federal rule, which in turn (in diversity cases) incorporates the claim-preclusion law that would be applied by state courts in the State in which the federal court sits, the Maryland Court of Special Appeals erred in holding that the California federal court's dismissal 'upon the merits' necessarily precluded the Maryland state-court action.\" Thus, the District Court's dismissal on the merits of claims as untimely under California law did not preclude Semtek from asserting its claims in a different state court forum.","sumSrc":"Oyez","by":{"0":"33, 34","1":"16"}},{"t":"case","label":"Serra v. Pichardo","cite":"786 F.2d 237","y":1986,"url":"https://www.courtlistener.com/c/F.2d/786/237/","sum":"Holding that “same subject matter” test is satisfied so long as “the substance of the Bivens claims reveals that they arise from the same actions toward plaintiff by defendants as those that defined the FTCA case”.","sumSrc":"brief:0","by":{"0":"6, 15"}},{"t":"case","label":"Shaffer v. Carter","cite":"252 U.S. 37","y":1920,"id":"scdb/1919-144","sc":1,"sum":"When, upon application for a preliminary injunction, the District Court not only refuses the injunction but dismisses the bill, appeal to this court should be under Jud. Code, § 238, frpm the final decree, and not under § 266.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Singleton v. United States","cite":"277 F.3d 864","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/277/864/","by":{"0":"38"}},{"t":"case","label":"Smith v. Marshall","cite":"885 F.2d 650","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/885/650/","by":{"0":"48"}},{"t":"case","label":"Sowell v. United States","cite":"835 F.2d 1133","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/835/1133/","by":{"0":"5"}},{"t":"case","label":"Steele v. Federal Bureau of Prisons","cite":"355 F.3d 1204","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/355/1204/","by":{"0":"38"}},{"t":"case","label":"Stepp v. United States","cite":"207 F.2d 909","y":1953,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/207/909/","by":{"0":"20"}},{"t":"case","label":"Stewart v. United States","cite":"486 F. Supp. 178","y":1980,"court":"C.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./486/178/","by":{"0":"26"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"United States v. Gaubert","cite":"499 U.S. 315","y":1991,"id":"1990/89-1793","sc":1,"op":2,"sum":"When the events in this case occurred, the Home Owners' Loan Act of 1933 authorized the Federal Home Loan Bank Board (FHLBB) to prescribe rules and regulations providing '\"for the organization, incorporation, examination, and regulation\" of federal savings and loan associations, and to issue charters, \"giving primary consideration to the best practices of thrift institutions in the United States.\" 12 U. S. C. § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"United States v. Gilman","cite":"347 U.S. 507","y":1954,"id":"scdb/1953-072","sc":1,"sum":"The United States is not entitled to recover indemnity from one of its employees for whose negligence it has been held liable under the Federal Tort Claims Act. Pp, 507-513. 206 F. 2d 846, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3, 12, 23, 24"}},{"t":"case","label":"United States v. S.A. Empresa de Viacao Aerea Rio Grandese","cite":"467 U.S. 797","y":1984,"id":"1983/82-1349","sc":1,"sum":"Government liability under the FTCA is limited by the discretionary function exception of 28 U.S.C. Section 2680(a), which provides that the federal government may not be held liable for \"[a]ny claim based upon an act or omission of an employee of the Government . . . based upon the exercise or performance or the failure to exercise or perform a discretionary function . . . whether or not the discretion involved be abused.\" The FAA's decision to institute the \"spot-check\" program to monitor compliance with its minimum safety standards was clearly discretionary and protected by Section 2680(a).","sumSrc":"Oyez","by":{"0":"25, 34"}},{"t":"case","label":"United States v. Smith","cite":"499 U.S. 160","y":1991,"id":"1990/89-1646","sc":1,"op":3,"sum":"The Act immunizes Government employees from suit even when an FTCA exception precludes recovery against the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 48, 49, 50","1":"2, 10, 12"}},{"t":"case","label":"United States v. United Mine Workers of Am.","cite":"330 U.S. 258","y":1947,"id":"scdb/1946-060","sc":1,"sum":"1. Neither the Norris-LaGuardia Act, 47 Stat. 70, nor § 20 of the Clayton Act, 38 Stat. 738, deprives a federal district court of jurisdiction to issue a restraining order and preliminary injunction in a suit by the Government to prevent a union and its officers from precipitating a nation-wide strike in the bituminous coal mines pending judicial interpretation of a labor contract between the Government and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Unus v. Kane","cite":"565 F.3d 103","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/565/103/","by":{"0":"6"}},{"t":"case","label":"Villanueva v. United States","cite":"708 F. Supp. 2","y":2009,"court":"D. Ariz.","url":"https://www.courtlistener.com/c/F.%20Supp./708/2/","by":{"0":"26"}},{"t":"case","label":"Westfall v. Erwin","cite":"484 U.S. 292","y":1988,"id":"1987/86-714","sc":1,"ar":6,"sum":"Conduct by federal officials must be discretionary in nature, as well as being within the scope of their employment, before the conduct is absolutely immune from state-law tort liability. See Doe v. McMillan, 412 U. S. 306. Granting absolute immunity for nondiscretionary functions would not further the official immunity doctrine's central purpose of promoting effective government by insulating the decisionmaking …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Wilcox v. United States","cite":"117 F. Supp. 119","y":1953,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./117/119/","by":{"0":"21"}},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"op":2,"ar":1,"sum":"The Court ruled that the Circuit Court had no jurisdiction to hear an appeal under the collateral order doctrine. Writing for the Court, Justice David Souter stressed the narrow scope of the doctrine. The Court reiterated that only orders that cannot be \"effectively\" reviewed after a final judgment can be appealed before the close of the trial.","sumSrc":"Oyez","by":{"0":"6, 12, 24, 25, 29","1":"19"}},{"t":"case","label":"Williams v. Fleming","cite":"597 F.3d 820","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/597/820/","op":1,"by":{"0":"5"}},{"t":"case","label":"Wohlford v. United States","cite":"823 F. Supp. 386","y":1992,"court":"W.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./823/386/","by":{"0":"38"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"0":"2, 8, 9, 10"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","stext":{"head":"§2671. Definitions","paras":[[0,"As used in this chapter and sections 1346(b) and 2401(b) of this title, the term \"Federal agency\" includes the executive departments, the judicial and legislative branches, the military departments, independent establishments of the United States, and corporations primarily acting as instrumentalities or agencies of the United States, but does not include any contractor with the United States."],[0,"\"Employee of the government\" includes (1) officers or employees of any federal agency, members of the military or naval forces of the United States, members of the National Guard while engaged in training or duty under section 115, 316, 502, 503, 504, or 505 of title 32, and persons acting on behalf of a federal agency in an official capacity, temporarily or permanently in the service of the United States, whether with or without compensation, and (2) any officer or employee of a Federal public defender organization, except when such officer or employee performs professional services in the course of providing representation under section 3006A of title 18."],[0,"\"Acting within the scope of his office or employment\", in the case of a member of the military or naval forces of the United States or a member of the National Guard as defined in section 101(3) of title 32, means acting in line of duty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2671?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2671. Definitions","tname":"Judiciary and Judicial Procedure","by":{"0":"51","1":"4, 6, 13"}},{"t":"usc","label":"28 U.S.C. § 2672","url":"https://www.law.cornell.edu/uscode/text/28/2672","by":{"0":"23"}},{"t":"usc","label":"28 U.S.C. § 2674","url":"https://www.law.cornell.edu/uscode/text/28/2674","stext":{"head":"§2674. Liability of United States","paras":[[0,"The United States shall be liable, respecting the provisions of this title relating to tort claims, in the same manner and to the same extent as a private individual under like circumstances, but shall not be liable for interest prior to judgment or for punitive damages."],[0,"If, however, in any case wherein death was caused, the law of the place where the act or omission complained of occurred provides, or has been construed to provide, for damages only punitive in nature, the United States shall be liable for actual or compensatory damages, measured by the pecuniary injuries resulting from such death to the persons respectively, for whose benefit the action was brought, in lieu thereof."],[0,"With respect to any claim under this chapter, the United States shall be entitled to assert any defense based upon judicial or legislative immunity which otherwise would have been available to the employee of the United States whose act or omission gave rise to the claim, as well as any other defenses to which the United States is entitled."],[0,"With respect to any claim to which this section applies, the Tennessee Valley Authority shall be entitled to assert any defense which otherwise would have been available to the employee based upon judicial or legislative immunity, which otherwise would have been available to the employee of the Tennessee Valley Authority whose act or omission gave rise to the claim as well as any other defenses to which the Tennessee Valley Authority is entitled under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2674?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§2674. Liability of United States","tname":"Judiciary and Judicial Procedure","by":{"0":"48","1":"3, 13"}},{"t":"usc","label":"28 U.S.C. § 2676","url":"https://www.law.cornell.edu/uscode/text/28/2676","stext":{"head":"§2676. Judgment as bar","paras":[[0,"The judgment in an action under section 1346(b) of this title shall constitute a complete bar to any action by the claimant, by reason of the same subject matter, against the employee of the government whose act or omission gave rise to the claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2676?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§2676. Judgment as bar","tname":"Judiciary and Judicial Procedure","by":{"0":"48","1":"1, 10, 11, 22"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(a)","(b)","(b)(1)","(b)(2)","(d)","(d)(1)","(d)(2)","(d)(3)","(d)(4)","(b)(2)(A)"],"stext":{"head":"§2679. Exclusiveness of remedy","paras":[[0,"(a) The authority of any federal agency to sue and be sued in its own name shall not be construed to authorize suits against such federal agency on claims which are cognizable under section 1346(b) of this title, and the remedies provided by this title in such cases shall be exclusive."],[0,"(b)(1) The remedy against the United States provided by sections 1346(b) and 2672 of this title for injury or loss of property, or personal injury or death arising or resulting from the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment is exclusive of any other civil action or proceeding for money damages by reason of the same subject matter against the employee whose act or omission gave rise to the claim or against the estate of such employee. Any other civil action or proceeding for money damages arising out of or relating to the same subject matter against the employee or the employee's estate is precluded without regard to when the act or omission occurred."],[0,"(2) Paragraph (1) does not extend or apply to a civil action against an employee of the Government—"],[1,"(A) which is brought for a violation of the Constitution of the United States, or"],[1,"(B) which is brought for a violation of a statute of the United States under which such action against an individual is otherwise authorized."],[0,"(c) The Attorney General shall defend any civil action or proceeding brought in any court against any employee of the Government or his estate for any such damage or injury. The employee against whom such civil action or proceeding is brought shall deliver within such time after date of service or knowledge of service as determined by the Attorney General, all process served upon him or an attested true copy thereof to his immediate superior or to whomever was designated by the head of his department to receive such papers and such person shall promptly furnish copies of the pleadings and process therein to the United States attorney for the district embracing the place wherein the proceeding is brought, to the Attorney General, and to the head of his employing Federal agency."],[0,"(d)(1) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a United States district court shall be deemed an action against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant."],[0,"(2) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a State court shall be removed without bond at any time before trial by the Attorney General to the district court of the United States for the district and division embracing the place in which the action or proceeding is pending. Such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. This certification of the Attorney General shall conclusively establish scope of office or employment for purposes of removal."],[0,"(3) In the event that the Attorney General has refused to certify scope of office or employment under this section, the employee may at any time before trial petition the court to find and certify that the employee was acting within the scope of his office or employment. Upon such certification by the court, such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. A copy of the petition shall be served upon the United States in accordance with the provisions of Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. In the event the petition is filed in a civil action or proceeding pending in a State court, the action or proceeding may be removed without bond by the Attorney General to the district court of the United States for the district and division embracing the place in which it is pending. If, in considering the petition, the district court determines that the employee was not acting within the scope of his office or employment, the action or proceeding shall be remanded to the State court."],[0,"(4) Upon certification, any action or proceeding subject to paragraph (1), (2), or (3) shall proceed in the same manner as any action against the United States filed pursuant to section 1346(b) of this title and shall be subject to the limitations and exceptions applicable to those actions."],[0,"(5) Whenever an action or proceeding in which the United States is substituted as the party defendant under this subsection is dismissed for failure first to present a claim pursuant to section 2675(a) of this title, such a claim shall be deemed to be timely presented under section 2401(b) of this title if—"],[1,"(A) the claim would have been timely had it been filed on the date the underlying civil action was commenced, and"],[1,"(B) the claim is presented to the appropriate Federal agency within 60 days after dismissal of the civil action."],[0,"(e) The Attorney General may compromise or settle any claim asserted in such civil action or proceeding in the manner provided in section 2677, and with the same effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2679?type=usc&year=mostrecent&link-type=html"},"head":"§2679. Exclusiveness of remedy","tname":"Judiciary and Judicial Procedure","by":{"0":"48, 48, 48, 48, 48, 48, 50, 50, 50, 50","1":"2, 8, 9, 11, 2, 10, 12, 21, 12, 13, 22, 12, 10, 12"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(a)","(c)","(h)","(j)","(k)","(l)","(m)","(n)"],"stext":{"head":"§2680. Exceptions","paras":[[0,"The provisions of this chapter and section 1346(b) of this title shall not apply to—"],[0,"(a) Any claim based upon an act or omission of an employee of the Government, exercising due care, in the execution of a statute or regulation, whether or not such statute or regulation be valid, or based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the part of a federal agency or an employee of the Government, whether or not the discretion involved be abused."],[0,"(b) Any claim arising out of the loss, miscarriage, or negligent transmission of letters or postal matter."],[0,"(c) Any claim arising in respect of the assessment or collection of any tax or customs duty, or the detention of any goods, merchandise, or other property by any officer of customs or excise or any other law enforcement officer, except that the provisions of this chapter and section 1346(b) of this title apply to any claim based on injury or loss of goods, merchandise, or other property, while in the possession of any officer of customs or excise or any other law enforcement officer, if—"],[1,"(1) the property was seized for the purpose of forfeiture under any provision of Federal law providing for the forfeiture of property other than as a sentence imposed upon conviction of a criminal offense;"],[1,"(2) the interest of the claimant was not forfeited;"],[1,"(3) the interest of the claimant was not remitted or mitigated (if the property was subject to forfeiture); and"],[1,"(4) the claimant was not convicted of a crime for which the interest of the claimant in the property was subject to forfeiture under a Federal criminal forfeiture law..1"],[0,"(d) Any claim for which a remedy is provided by chapter 309 or 311 of title 46 relating to claims or suits in admiralty against the United States."],[0,"(e) Any claim arising out of an act or omission of any employee of the Government in administering the provisions of sections 1–31 of Title 50, Appendix.2"],[0,"(f) Any claim for damages caused by the imposition or establishment of a quarantine by the United States."],[0,"[(g) Repealed. Sept. 26, 1950, ch. 1049, §13 (5), 64 Stat. 1043.]"],[0,"(h) Any claim arising out of assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights: Provided, That, with regard to acts or omissions of investigative or law enforcement officers of the United States Government, the provisions of this chapter and section 1346(b) of this title shall apply to any claim arising, on or after the date of the enactment of this proviso, out of assault, battery, false imprisonment, false arrest, abuse of process, or malicious prosecution. For the purpose of this subsection, \"investigative or law enforcement officer\" means any officer of the United States who is empowered by law to execute searches, to seize evidence, or to make arrests for violations of Federal law."],[0,"(i) Any claim for damages caused by the fiscal operations of the Treasury or by the regulation of the monetary system."],[0,"(j) Any claim arising out of the combatant activities of the military or naval forces, or the Coast Guard, during time of war."],[0,"(k) Any claim arising in a foreign country."],[0,"(l) Any claim arising from the activities of the Tennessee Valley Authority."],[0,"(m) Any claim arising from the activities of the Panama Canal Company."],[0,"(n) Any claim arising from the activities of a Federal land bank, a Federal intermediate credit bank, or a bank for cooperatives."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2680?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§2680. Exceptions","tname":"Judiciary and Judicial Procedure","by":{"0":"50, 50, 50, 7, 7, 7, 7","1":"passim, 7, 9, 10, 9, 10, 9, 10, 10, 2"}},{"t":"usc","label":"18 U.S.C. § 2251","url":"https://www.law.cornell.edu/uscode/text/18/2251","subs":["(b)"],"by":{"0":"7"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)","(b)(1)"],"stext":{"head":"§1346. United States as defendant","paras":[[0,"(a) The district courts shall have original jurisdiction, concurrent with the United States Court of Federal Claims, of:"],[1,"(1) Any civil action against the United States for the recovery of any internal-revenue tax alleged to have been erroneously or illegally assessed or collected, or any penalty claimed to have been collected without authority or any sum alleged to have been excessive or in any manner wrongfully collected under the internal-revenue laws;"],[1,"(2) Any other civil action or claim against the United States, not exceeding $10,000 in amount, founded either upon the Constitution, or any Act of Congress, or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort, except that the district courts shall not have jurisdiction of any civil action or claim against the United States founded upon any express or implied contract with the United States or for liquidated or unliquidated damages in cases not sounding in tort which are subject to sections 7104(b)(1) and 7107(a)(1) of title 41. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(b)(1) Subject to the provisions of chapter 171 of this title, the district courts, together with the United States District Court for the District of the Canal Zone and the District Court of the Virgin Islands, shall have exclusive jurisdiction of civil actions on claims against the United States, for money damages, accruing on and after January 1, 1945, for injury or loss of property, or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred."],[0,"(2) No person convicted of a felony who is incarcerated while awaiting sentencing or while serving a sentence may bring a civil action against the United States or an agency, officer, or employee of the Government, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(c) The jurisdiction conferred by this section includes jurisdiction of any set-off, counterclaim, or other claim or demand whatever on the part of the United States against any plaintiff commencing an action under this section."],[0,"(d) The district courts shall not have jurisdiction under this section of any civil action or claim for a pension."],[0,"(e) The district courts shall have original jurisdiction of any civil action against the United States provided in section 6226, 6228(a), 7426, or 7428 (in the case of the United States district court for the District of Columbia) or section 7429 of the Internal Revenue Code of 1986."],[0,"(f) The district courts shall have exclusive original jurisdiction of civil actions under section 2409a to quiet title to an estate or interest in real property in which an interest is claimed by the United States."],[0,"(g) Subject to the provisions of chapter 179, the district courts of the United States shall have exclusive jurisdiction over any civil action commenced under section 453(2) of title 3, by a covered employee under chapter 5 of such title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1346?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1346. United States as defendant","tname":"Judiciary and Judicial Procedure","by":{"0":"3, 5, 9, 9","1":"passim"}},{"t":"usc","label":"28 U.S.C. § 1915","url":"https://www.law.cornell.edu/uscode/text/28/1915","subs":["(e)"],"by":{"0":"9"}},{"t":"case","label":"Atlantic Coast Conference v. University of Md.","cite":"751 S.E.2d 612","y":2013,"court":"N.C. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/751/612/","by":{"1":"16"}},{"t":"case","label":"Edelman v. FHA","cite":"382 F.2d 594","y":1967,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/382/594/","by":{"1":"9"}},{"t":"case","label":"Expeditions Unlimited Aquatic Enters., Inc. v. Smithsonian Inst.","cite":"566 F.2d 289","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/566/289/","by":{"1":"9"}},{"t":"case","label":"FDIC v. Citizens Bank & Trust Co.","cite":"592 F.2d 364","y":1979,"url":"https://www.courtlistener.com/c/F.2d/592/364/","by":{"1":"9"}},{"t":"case","label":"Hui v. Castaneda","cite":"599 U.S. 799","y":2010,"id":"2009/08-1529","sc":1,"sum":"The Court held that the immunity granted by the Federal Tort Claims Act precludes Bivens actions against Public Health Service officers for constitutional violations committed while in the scope of the employees' official duties.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Manning v. United States","cite":"546 F.3d 430","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/546/430/","sum":"Noting that Bivens plaintiff can “voluntarily withdraw a contemporaneous FTCA claim”.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"Safeway Portland E.F.C.U. v. FDIC","cite":"506 F.2d 594","y":1967,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/506/594/","by":{"1":"9"}},{"t":"case","label":"Sterrett v. Milk River Prod. Credit Ass’n","cite":"647 F. Supp. 299","y":1986,"court":"D. Mont.","url":"https://www.courtlistener.com/c/F.%20Supp./647/299/","by":{"1":"10"}},{"t":"case","label":"Texas Dep’t of Transp. v. Jones","cite":"8 S.W.3d 636","y":1999,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/8/636/","by":{"1":"16"}},{"t":"case","label":"Tinsley v. Washington Metro. Area Transit Auth.","cite":"55 A.3d 663","y":2012,"court":"Md.","url":"https://www.courtlistener.com/c/A.3d/55/663/","by":{"1":"16"}},{"t":"case","label":"United States v. Ruiz","cite":"536 U.S. 622","y":2002,"id":"2001/01-595","sc":1,"sum":"The Court held that the Constitution does not require the Government to disclose material impeachment evidence prior to entering a plea agreement with a criminal defendant.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"United States v. Spelar","cite":"338 U.S. 217","y":1949,"id":"scdb/1949-001","sc":1,"sum":"The Federal Tort Claims Act, which is inapplicable by its terms to any claim \"arising in a foreign country,\" does not authorize an action against the United States for an allegedly wrongful death occurring at a Newfoundland air base under long-term lease from Great Britain to the United States and allegedly resulting from the negligent operation of the air base by the United States. VermilyaBrown Co. v. Connell, 335 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 89-506","url":"https://www.govinfo.gov/link/statute/80/306","by":{"1":"6"}},{"t":"usc","label":"28 U.S.C. § 2675","url":"https://www.law.cornell.edu/uscode/text/28/2675","by":{"1":"5, 6"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","by":{"1":"4"}},{"t":"usc","label":"18 U.S.C. § 1963","url":"https://www.law.cornell.edu/uscode/text/18/1963","by":{"1":"4"}},{"t":"usc","label":"28 U.S.C. § 1406","url":"https://www.law.cornell.edu/uscode/text/28/1406","by":{"1":"21"}},{"t":"usc","label":"42 U.S.C. § 233","url":"https://www.law.cornell.edu/uscode/text/42/233","subs":["(a)"],"by":{"1":"21"}}]};